import React from 'react';
import logo from "../Images/paylync.png"

const Header = () => {
  return (
    <header className="sticky top-0 w-full h-16 bg-white border-b flex items-center justify-between px-4 shadow-sm z-10">
      <div className="flex items-center gap-2">
        <img src={logo} alt="Logo" className="w-24 h-12" />
        <div className="h-8 w-[1.75px] bg-gray-300 ml-1 mr-4 dark:bg-gray-600"></div>

        <h1 className="text-lg font-semibold">Free Invoice Generator</h1>
      </div>
      {/* <div>
        <button className="text-blue-600 text-sm font-medium">Sign up. It’s Free!</button>
      </div> */}
    </header>
  );
};

export default Header;
