import React from "react";
import { pdf } from "@react-pdf/renderer";
import StandardPdf from "./Standard";
import SpreadsheetPdf from "./Spreadsheet";
import CompactPdf from "./Compact";

interface ReceiptGeneratorProps {
  invoiceData: {
    companyLogo: string | null;
    companyName: string;
    yourName: string;
    companyAddress: string;
    cityStateZip: string;
    country: string;
    clientCompany: string;
    clientAddress: string;
    clientCityStateZip: string;
    clientCountry: string;
    invoiceNumber: string;
    invoiceDate: string;
    dueDate: string;
    items: Array<{
      id: number;
      description: string;
      quantity: number;
      rate: number;
      tax: number;
    }>;
    subTotal: number;
    discount: number;
    discountType: 'percent' | 'fixed';
    taxTotal: number;
    total: number;
    notes: string;
    terms: string;
    selectColor: string;
    selectedTheme: string;
  };
  onPrint?: () => void;
  onDownload?: () => void;
}

// Create a utility function outside the component
export const generateReceipt = async (invoiceData: ReceiptGeneratorProps["invoiceData"], action: "print" | "download") => {
  try {
    // Create the PDF document based on the selected theme
    let pdfDoc;
    
    // Select the appropriate template based on the theme
    if (invoiceData.selectedTheme === "standard") {
      pdfDoc = <StandardPdf invoiceData={invoiceData} />;
    } else if (invoiceData.selectedTheme === "spreadsheet") {
      pdfDoc = <SpreadsheetPdf invoiceData={invoiceData} />;
    } else if (invoiceData.selectedTheme === "compact") {
      pdfDoc = <CompactPdf invoiceData={invoiceData} />;
    } else {
      // Default to standard
      pdfDoc = <StandardPdf invoiceData={invoiceData} />;
    }

    // Generate the PDF blob
    const blob = await pdf(pdfDoc).toBlob();
    const url = URL.createObjectURL(blob);

    if (action === "print") {
      // Open in a new window for printing
      const printWindow = window.open(url);
      if (printWindow) {
        printWindow.onload = function () {
          printWindow.focus();
          printWindow.print();
        };
      } else {
        alert("Popup blocked! Please allow popups for this site.");
      }
    } else if (action === "download") {
      // Create a download link
      const link = document.createElement("a");
      link.href = url;
      link.download = `invoice-${invoiceData.invoiceNumber || "default"}.pdf`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  } catch (error) {
    console.error("Error generating PDF:", error);
    alert("Failed to generate PDF. Please try again.");
  }
};

// This component doesn't render anything, it just provides the functionality
const ReceiptGenerator: React.FC<ReceiptGeneratorProps> = ({ invoiceData, onPrint, onDownload }) => {
  // The component itself doesn't render anything visible
  return null;
};

export default ReceiptGenerator; 